package net.softm.data.kata.common;

import net.softm.data.kata.WApplication;
import net.softm.data.kata.util.PackageUtil;
import net.softm.data.kata.util.Utils;

import java.util.HashMap;

public enum PackageMusic {
    SAMSUNG_MUSIC( 1,"com.sec.android.app.music"             ,"data:image/webp;base64,"),// Samsung Music
    YOUTUBE_MUSIC( 2,"com.google.android.apps.youtube.music" ,"data:image/webp;base64,"),// YouTube Music
    YOUTUBE      ( 3,"com.google.android.youtube"            ,"data:image/webp;base64,"),// YouTube
    APPLE_MUSIC  ( 4,"com.apple.android.music"               ,"data:image/webp;base64,"),// Apple Music
    SPOTIFY      ( 5,"com.spotify.music"                     ,"data:image/webp;base64,"),// Spotify
    MUSIC_PLAYER ( 6,"com.media.music.mp3.musicplayer"       ,"data:image/webp;base64,"),// Music player
    GENIE_MUSIC  ( 7,"com.ktmusic.geniemusic"                ,"data:image/webp;base64,"),// 지니뮤직 - genie
    NAVER_VIBE   ( 8,"com.naver.vibe"                        ,"data:image/webp;base64,"),// 네이버 VIBE (바이브)
    MELON        ( 9,"com.iloen.melon"                       ,"data:image/webp;base64,"),// 멜론(Melon)
    SOUNDCLOUD   (10,"com.soundcloud.android"                ,"data:image/webp;base64,"),// SoundCloud - 음악과 오디오
    MP3_PLAYER   (11,"musicplayer.musicapps.music.mp3player" ,"data:image/webp;base64,"),// Music Player & MP3 Player
    FLO          (12,"skplanet.musicmate"                    ,"data:image/webp;base64,"),// FLO – 플로
    BUGS         (13,"com.neowiz.android.bugs"               ,"data:image/webp;base64,"),// 벅스 - Bugs
    KAKAOMUSIC   (14,"com.kakao.music"                       ,"data:image/webp;base64,"),// KakaoMusic
    MI_MUSIC     (15,"com.miui.player"                       ,"data:image/webp;base64,"),// Mi Music
    ;

    private Integer seq;
    private String id;
    private String icon;
    private String name;
    PackageMusic(int seq, String id, String icon) {
        this.seq = seq;
        this.id = id;
        this.icon = icon;
    }
    public Integer getSeq() {
        return seq;
    }
    public String getId() {
        return id;
    }
    public String getIcon() {
        return icon;
    }

    public String getName() {
        int resourceId = WApplication.mInstance.getResources().getIdentifier("app_name_" + id,"string",WApplication.mInstance.getPackageName());
        this.name = WApplication.mInstance.getString(resourceId);
        return name;
    }

    public boolean equals(String id) {
        return this.id.equals(id);
    }
    public static HashMap<String, Object> getPakages() {
        return getPakages("");
    }
    public static HashMap<String, Object> getPakages(String key) {
        HashMap<String, Object> pkgs = new HashMap<String, Object>();
        for (PackageMusic pkg : PackageMusic.values()) {
            if ( pkg.getSeq() > 0 ) {
                if (Utils.isEmpty(key)) {
                    HashMap<String, Object> appInfo = PackageUtil.getAppInfo(pkg.getId());
                    if (Utils.isEmpty(appInfo.get("name"))) {
                        appInfo.put("icon", pkg.getIcon());
                        appInfo.put("name", pkg.getName());
                        appInfo.put("installed", false);
                    }
                    appInfo.put("seq", pkg.getSeq());
                    pkgs.put(pkg.getId(), appInfo);
                } else {
                    if (pkg.getId().equals(key)) {
                        HashMap<String, Object> appInfo = PackageUtil.getAppInfo(key);
                        if (Utils.isEmpty(appInfo.get("name"))) {
                            appInfo.put("icon", pkg.getIcon());
                            appInfo.put("name", pkg.getName());
                            appInfo.put("installed", false);
                        }
                        appInfo.put("seq", pkg.getSeq());
                        pkgs.put(pkg.getId(), appInfo);
                    }
                }
            }
        }
        return pkgs;
    }

    public static final String aa = PackageMusic.SAMSUNG_MUSIC.id;
    public static PackageMusic value(String id) {
        PackageMusic rtn = null;
        switch (id) {
            case "com.sec.android.app.music" :
                rtn = PackageMusic.SAMSUNG_MUSIC;
                break;
            case "com.google.android.apps.youtube.music" :
                rtn = PackageMusic.YOUTUBE_MUSIC;
                break;
            case "com.google.android.youtube" :
                rtn = PackageMusic.YOUTUBE;
                break;
            case "com.apple.android.music":
                rtn = PackageMusic.APPLE_MUSIC;
                break;
            case "com.spotify.music"  :
                rtn = PackageMusic.SPOTIFY;
                break;
            case "com.media.music.mp3.musicplayer":
                rtn = PackageMusic.MUSIC_PLAYER;
                break;
            case "com.ktmusic.geniemusic" :
                rtn = PackageMusic.GENIE_MUSIC;
                break;
            case "com.naver.vibe":
                rtn = PackageMusic.NAVER_VIBE;
                break;
            case "com.iloen.melon":
                rtn = PackageMusic.MELON;
                break;
            case "com.soundcloud.android":
                rtn = PackageMusic.SOUNDCLOUD;
                break;
            case "musicplayer.musicapps.music.mp3player":
                rtn = PackageMusic.MP3_PLAYER;
                break;
            case "skplanet.musicmate" :
                rtn = PackageMusic.FLO;
                break;
            case "com.neowiz.android.bugs":
                rtn = PackageMusic.BUGS;
                break;
            case "com.kakao.music":
                rtn = PackageMusic.KAKAOMUSIC;
                break;
            case "com.miui.player" :
                rtn = PackageMusic.MI_MUSIC;
                break;
            default:
                break;
        }
        return rtn;
    }
}
